  ('amrmscll', 'Full-stack Software Engineer', 'Computer Science and AI graduate of FCAI, Cairo University, building document-intelligence software at Syntheia. A normal week touches a TypeScript API, a React front end, a Python ML service and a Helm chart. Most useful where those meet, and most interested in whichever part I have not done before.', '[{"type":"stack","groups":[{"group":"languages","items":["TypeScript","JavaScript","Python","C++","SQL"]},{"group":"backend","items":["NestJS","Express","FastAPI","Django","Prisma","GraphQL"]},{"group":"frontend","items":["React","Redux Toolkit","Tailwind","MUI","Vite","Office.js"]},{"group":"data","items":["PostgreSQL","MongoDB","Redis","Qdrant","Milvus"]},{"group":"ml","items":["PyTorch","Transformers","spaCy","scikit-learn","Celery"]},{"group":"platform","items":["Docker","Kubernetes","Helm","Terraform","AWS","Azure"]},{"group":"testing","items":["Jest","Pytest","Playwright","SonarQube"]}]},{"type":"links","links":[{"label":"github","url":"https://github.com/AmrMsCLL"},{"label":"linkedin","url":"https://www.linkedin.com/in/amrsherieycll"},{"label":"email","url":"mailto:amrsherieycll@gmail.com"},{"label":"discord","url":"https://discord.com/users/412317378337046529"}]}]', '2026-11-05T00:00:00.000Z'),
  ('bluocaroot', 'Software Engineer at Syntheia', 'Software engineer from Egypt, building document-intelligence software at Syntheia: a NestJS API, a React portal and an Outlook add-in on Office.js. Came up through competitive programming, which still shapes how I approach problems, and outside work I build tools like Digital to Physical to learn the parts of the stack I have not touched yet.', '[{"type":"stack","groups":[{"group":"languages","items":["TypeScript","JavaScript","C++","Python","C","SQL"]},{"group":"backend","items":["NestJS","Node.js","Express","GraphQL"]},{"group":"frontend","items":["React","MUI","Tailwind","Vite","Office.js"]},{"group":"data","items":["PostgreSQL","MongoDB"]},{"group":"platform","items":["Docker","Azure","Linux","Git"]},{"group":"testing","items":["Jest","SonarQube"]}]},{"type":"links","links":[{"label":"github","url":"https://github.com/BluoCaroot"},{"label":"linkedin","url":"https://www.linkedin.com/in/assem-amr-abdelfattah/"},{"label":"codeforces","url":"https://codeforces.com/profile/BluoCaroot"}]}]', '2026-11-05T00:00:00.000Z'),
  ('mahmoudhanyfathalla', NULL, NULL, '[{"type":"links","links":[{"label":"github","url":"https://github.com/MahmoudHanyFathalla"}]}]', '2026-11-05T00:00:00.000Z'),
  ('omar-mohamed24', 'Backend & Full-stack Software Engineer', 'Software engineer who goes looking for the hard parts. Wrote a Game Boy emulator from scratch in C++20, compiled it to WebAssembly and shipped it as PixelPocket, where it passes all of Blarggs CPU tests and plays in any browser. Built GameForge, a ten-service platform where an LLM planner, an MCP asset pipeline and a Godot build step turn one sentence into a playable game. Codeforces Expert with 1000+ problems solved, CS graduate of FCAI, Cairo University, and formerly a prompt engineer at Scale AI.', '[{"type":"stack","groups":[{"group":"languages","items":["C++","JavaScript","Python","Java","C#"]},{"group":"backend","items":["Node.js","Express","Django","REST APIs","Microservices"]},{"group":"frontend","items":["React","WebAssembly","HTML","CSS"]},{"group":"data","items":["MongoDB","MySQL","MinIO"]},{"group":"ai","items":["LLM Integration","MCP","Stability AI","Prompt Engineering"]},{"group":"platform","items":["Docker","Docker Compose","GitHub Actions","Linux","Git"]}]},{"type":"links","links":[{"label":"github","url":"https://github.com/Omar-Mohamed24"},{"label":"linkedin","url":"https://www.linkedin.com/in/omar-mohamed-8034032a3"},{"label":"email","url":"mailto:omarmohamed67371@gmail.com"},{"label":"codeforces","url":"https://codeforces.com/profile/Maliiketh"}]}]', '2026-11-05T00:00:00.000Z');
